export function themeFor(n: number): NumberTheme {
  return NUMBER_THEMES[n] || NUMBER_THEMES[reduceNumber(n, false)] || NUMBER_THEMES[9];
}

/** Days of the month whose digits reduce to the same single digit as `n` (for 5: 5, 14, 23). */
export function datesForNumber(n: number): number[] {
  const root = reduceNumber(n, false);
  return Array.from({ length: 31 }, (_, i) => i + 1).filter((d) => reduceNumber(d, false) === root);
}

// ── Whole profile ────────────────────────────────────────────────────────────

export interface NameProfile {
  name: string;
  letters: string;
  dob: string;
  zodiac: string;
  destiny: Working;
  soulUrge: Working;
  personality: Working;
  chaldean: Working;
  lifePath: DateWorking;
  birth: { day: number; chain: number[]; result: number };
}

export function buildProfile(name: string, dob: string): NameProfile | { error: string } {
  const c = checkName(name);
  if (!c.ok) return { error: c.error };
  return {
    name: c.display,
    letters: c.letters,
    dob,
    zodiac: zodiacFromDob(dob),
    destiny: destinyWorking(c.letters),
    soulUrge: soulUrgeWorking(c.letters),
    personality: personalityWorking(c.letters),
    chaldean: chaldeanWorking(c.letters),
    lifePath: lifePathWorking(dob),
    birth: birthNumberWorking(dob),
  };
}
